﻿*{
	line-height: 2;
}
header, footer {
		width:100%;
		text-align: center;
   		}
nav	{
	width: 30%;
	height:400px;
	float:left;
}
section {
width: 70%;
height:400px;
float:left;
}
iframe{
	width:100%;
	height:100%;
}
legend{
font-weight:bold;
font-size:14px;	
}
fieldset{
	border:  2px black solid;
}

a:visited{
	color: red;
}


label{
	display: inline-block;
	width: 150px;
}


#desc,#prix , #codehab , #cin , #duree{
	margin: 2px;
	color: blue;
	border: solid blue ;
}

